From 67629bda51a8c5a6155519d8c0a64c4be1a434bc Mon Sep 17 00:00:00 2001
From: =?UTF-8?q?Niccol=C3=B2=20Venerandi?= <niccolo@venerandi.com>
Date: Thu, 26 Nov 2026 18:31:18 +0100
Subject: [PATCH] greeter: let the lock screen turn off the screens

Only the Escape key could turn off the screens from the lock screen, so
the QML had no way to offer a visible button for it. LockscreenState now
exposes canTurnOffScreens and turnOffScreens(), shared with Escape.

BUG: 427990
---
 greeter/greeterapp.cpp | 45 +++++++++++++++++++++++++++++++-----------
 greeter/greeterapp.h   | 16 +++++++++++++++
 2 files changed, 49 insertions(+), 12 deletions(-)

diff --git a/greeter/greeterapp.cpp b/greeter/greeterapp.cpp
index ec4283b1..33b3a4bc 100644
--- a/greeter/greeterapp.cpp
+++ b/greeter/greeterapp.cpp
@@ -113,6 +113,20 @@ void LockscreenState::init(UnlockApp *app)
 {
     if (!m_parentApp) {
         m_parentApp = app;
+        connect(app, &UnlockApp::canTurnOffScreensChanged, this, &LockscreenState::canTurnOffScreensChanged);
+        Q_EMIT canTurnOffScreensChanged();
+    }
+}
+
+bool LockscreenState::canTurnOffScreens() const
+{
+    return m_parentApp && m_parentApp->canTurnOffScreens();
+}
+
+void LockscreenState::turnOffScreens()
+{
+    if (m_parentApp) {
+        m_parentApp->turnOffScreens();
     }
 }

@@ -169,6 +183,11 @@ UnlockApp::UnlockApp(int &argc, char **argv)

     m_authenticators = new PamAuthenticators(KUser().loginName(), this);

+    if (KWindowSystem::isPlatformWayland()) {
+        m_dpms = new KScreen::Dpms(this);
+        connect(m_dpms, &KScreen::Dpms::supportedChanged, this, &UnlockApp::canTurnOffScreensChanged);
+    }
+
     auto state = m_engine->singletonInstance<LockscreenState *>("org.kde.kscreenlocker", "LockscreenState");
     state->init(this);

@@ -544,25 +563,27 @@ bool UnlockApp::eventFilter(QObject *obj, QEvent *event)
         QKeyEvent *ke = static_cast<QKeyEvent *>(event);
         if (ke->key() != Qt::Key_Escape) {
             return false; // irrelevant
-        } else if (!m_testing) { // don't turn screen off in testing mode.
-            auto dpms = new KScreen::Dpms(this);
-            if (dpms->isSupported()) {
-                connect(dpms, &KScreen::Dpms::hasPendingChangesChanged, this, [dpms](bool hasPendingChanges) {
-                    if (!hasPendingChanges) {
-                        dpms->deleteLater();
-                    }
-                });
-                dpms->switchMode(KScreen::Dpms::Off);
-            } else {
-                dpms->deleteLater();
-            }
         }
+        turnOffScreens();
         return true; // don't pass
     }

     return false;
 }

+bool UnlockApp::canTurnOffScreens() const
+{
+    return m_dpms && m_dpms->isSupported();
+}
+
+void UnlockApp::turnOffScreens()
+{
+    if (m_testing || !canTurnOffScreens()) { // don't turn screen off in testing mode.
+        return;
+    }
+    m_dpms->switchMode(KScreen::Dpms::Off);
+}
+
 void UnlockApp::setGraceTime(int milliseconds)
 {
     m_graceTime = milliseconds;
diff --git a/greeter/greeterapp.h b/greeter/greeterapp.h
index 84bb1199..cdbc89e8 100644
--- a/greeter/greeterapp.h
+++ b/greeter/greeterapp.h
@@ -28,6 +28,11 @@ class LogindIntegration;

 class PamAuthenticators;

+namespace KScreen
+{
+class Dpms;
+}
+
 namespace ScreenLocker
 {
 class WallpaperIntegration;
@@ -50,6 +55,8 @@ public:
     void setNoLock(bool noLock);
     void updateCanSuspend();
     void updateCanHibernate();
+    bool canTurnOffScreens() const;
+    void turnOffScreens();

 public Q_SLOTS:
     void osdProgress(const QString &icon, int percent, const int maximumPercent, const QString &additionalText);
@@ -57,6 +64,7 @@ public Q_SLOTS:

 Q_SIGNALS:
     void viewEntered(QQuickView *view);
+    void canTurnOffScreensChanged();

 protected:
     bool eventFilter(QObject *obj, QEvent *event) override;
@@ -89,6 +97,7 @@ private:
     KPackage::Package m_wallpaperPackage;
     ShellIntegration *m_shellIntegration;
     LogindIntegration *m_logindIntegration;
+    KScreen::Dpms *m_dpms = nullptr;
     std::shared_ptr<QQmlEngine> m_engine;
 };

@@ -98,11 +107,18 @@ class LockscreenState : public QObject
     QML_ELEMENT
     QML_SINGLETON

+    Q_PROPERTY(bool canTurnOffScreens READ canTurnOffScreens NOTIFY canTurnOffScreensChanged FINAL)
+
 public:
     static LockscreenState *create(QQmlEngine *, QJSEngine *);
     void init(UnlockApp *app);
+    [[nodiscard]] bool canTurnOffScreens() const;
+    Q_INVOKABLE void turnOffScreens();
     UnlockApp *m_parentApp;

+Q_SIGNALS:
+    void canTurnOffScreensChanged();
+
 private:
     explicit LockscreenState(QObject *parent = nullptr);
 };
